// bendc -o
// ========
//
// `bendc -o prog base.bend prog.bend` builds a binary. Cc.begin sends what
// bendc writes (the program's C) to a temporary file; Cc.end compiles it with
// $CC (default cc) against the runtime compiled once: bendrt.o beside the
// bendc executable, built from rt/bendrt_impl.c when it is missing or older.
// The runtime's directory is ../rt from the executable, or $BENDC_RT. A
// program then compiles only its own code.

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#ifdef __APPLE__
#include <mach-o/dyld.h>
#endif

static int cc_saved = -1;
static char cc_tmp[PATH_MAX];

// The directory of the running executable.
static int cc_exe_dir(char *out, size_t n) {
  char path[PATH_MAX];
#ifdef __APPLE__
  uint32_t sz = sizeof path;
  if (_NSGetExecutablePath(path, &sz) != 0) return -1;
#else
  ssize_t k = readlink("/proc/self/exe", path, sizeof path - 1);
  if (k < 0) return -1;
  path[k] = 0;
#endif
  char real[PATH_MAX];
  if (!realpath(path, real)) return -1;
  char *slash = strrchr(real, '/');
  if (!slash) return -1;
  *slash = 0;
  snprintf(out, n, "%s", real);
  return 0;
}

// $CC, or cc. On arm64 Macs cc is clang, whose machine outliner (on at -O2
// there) moves the matches' repeated tails into shared functions, a call and
// a return each on the hottest paths: without it tree-matmul runs 12% fewer
// cycles (and bitonic and radix the same).
static const char *cc_cmd(void) {
  if (getenv("CC") && *getenv("CC")) return getenv("CC");
#if defined(__APPLE__) && defined(__aarch64__)
  return "cc -mno-outline";
#else
  return "cc";
#endif
}

static long cc_mtime(const char *p) {
  struct stat st;
  return stat(p, &st) == 0 ? (long)st.st_mtime : -1;
}

Term cc_begin_run(Env e, Term *f, IoWork *w) {
  (void)f;
  (void)w;
  fflush(stdout);
  snprintf(cc_tmp, sizeof cc_tmp, "%s/bendc-XXXXXX.c", getenv("TMPDIR") ? getenv("TMPDIR") : "/tmp");
  int fd = mkstemps(cc_tmp, 2);
  if (fd < 0) return io_fail(e, (u32)errno, "cannot make a temporary file");
  cc_saved = dup(1);
  dup2(fd, 1);
  close(fd);
  return io_done(e, term_pak(CID_UNIT, 0));
}

static Term cc_fail(Env e, const char *msg) {
  unlink(cc_tmp);
  return io_fail(e, 1, msg);
}

// A program compiles with -fno-tree-slp-vectorize (clang and gcc both take
// it, tcc ignores it). The straight-line vectorizer gained nothing on the
// benchmarks, and in nbody whether it packed the 3-body loop into 2-lane
// vectors turned on unrelated code before the loop, costing 18% of the
// cycles when it did. It compiles at -O3, as the official bend does: in
// mandelbrot's escape loop clang -O3 kept the escape test a branch, where
// -O2 folded it into the selects of every step, and the loop ran 2.7 times
// fewer cycles (7.3G against 19.7G); the other benchmarks moved by 0 to 3%
// fewer instructions. Loops start on 16-byte boundaries (-falign-loops=16;
// clang on Apple arm64 does not align them): editdist's 22-instruction DP
// loop otherwise moved with unrelated code, and at 4 bytes short of a
// 64-byte line it ran 25% more cycles (10.7G against 8.5G).
Term cc_end_run(Env e, Term *f, IoWork *w) {
  (void)w;
  u64 n;
  char *out = io_cstr(e, f[0], &n);
  fflush(stdout);
  if (cc_saved >= 0) {
    dup2(cc_saved, 1);
    close(cc_saved);
    cc_saved = -1;
  }
  char dir[PATH_MAX], rt[PATH_MAX], obj[PATH_MAX], impl[PATH_MAX], hdr[PATH_MAX];
  if (cc_exe_dir(dir, sizeof dir) != 0) { free(out); return cc_fail(e, "cannot find the bendc executable"); }
  const char *env_rt = getenv("BENDC_RT");
  if (env_rt && *env_rt) snprintf(rt, sizeof rt, "%s", env_rt);
  else snprintf(rt, sizeof rt, "%s/../rt", dir);
  snprintf(obj, sizeof obj, "%s/bendrt.o", dir);
  snprintf(impl, sizeof impl, "%s/bendrt_impl.c", rt);
  snprintf(hdr, sizeof hdr, "%s/bendrt_split.h", rt);
  const char *cc = cc_cmd();
  size_t cl = strlen(cc) + 3 * PATH_MAX + strlen(out) + 256;
  char *cmd = malloc(cl);
  if (cc_mtime(obj) < 0 || cc_mtime(obj) < cc_mtime(impl) || cc_mtime(obj) < cc_mtime(hdr)) {
    snprintf(cmd, cl, "%s -O2 -w -I '%s' -c '%s' -o '%s.tmp' && mv '%s.tmp' '%s'", cc, rt, impl, obj, obj, obj);
    if (system(cmd) != 0) { free(cmd); free(out); return cc_fail(e, "the runtime (bendrt.o) does not compile"); }
  }
#ifdef __APPLE__
  const char *libs = "-lm -lpthread";
#else
  const char *libs = "-lm -lpthread -ldl";
#endif
  snprintf(cmd, cl, "%s -O3 -fno-tree-slp-vectorize -falign-loops=16 -w -DBEND_RT_SPLIT -I '%s' '%s' '%s' -o '%s' %s", cc, rt, cc_tmp, obj, out, libs);
  int rc = system(cmd);
  free(cmd);
  free(out);
  if (rc != 0) return cc_fail(e, "the C compiler failed");
  unlink(cc_tmp);
  return io_done(e, term_pak(CID_UNIT, 0));
}

// bendc --native: out.o holds the program's code (bendc wrote it, in
// machine code); the temporary file, the C of its effects. Both link with the
// runtime and rt/native.c (natives.o beside bendrt.o, built the same way).
Term cc_link_run(Env e, Term *f, IoWork *w) {
  (void)w;
  u64 n;
  char *out = io_cstr(e, f[0], &n);
  fflush(stdout);
  if (cc_saved >= 0) {
    dup2(cc_saved, 1);
    close(cc_saved);
    cc_saved = -1;
  }
  char dir[PATH_MAX], rt[PATH_MAX], obj[PATH_MAX], impl[PATH_MAX], hdr[PATH_MAX], nobj[PATH_MAX], nsrc[PATH_MAX];
  if (cc_exe_dir(dir, sizeof dir) != 0) { free(out); return cc_fail(e, "cannot find the bendc executable"); }
  const char *env_rt = getenv("BENDC_RT");
  if (env_rt && *env_rt) snprintf(rt, sizeof rt, "%s", env_rt);
  else snprintf(rt, sizeof rt, "%s/../rt", dir);
  snprintf(obj, sizeof obj, "%s/bendrt.o", dir);
  snprintf(nobj, sizeof nobj, "%s/natives.o", dir);
  snprintf(impl, sizeof impl, "%s/bendrt_impl.c", rt);
  snprintf(nsrc, sizeof nsrc, "%s/native.c", rt);
  snprintf(hdr, sizeof hdr, "%s/bendrt_split.h", rt);
  const char *cc = cc_cmd();
  size_t cl = strlen(cc) + 6 * PATH_MAX + 3 * strlen(out) + 256;
  char *cmd = malloc(cl);
  const char *srcs[2] = {impl, nsrc};
  const char *objs[2] = {obj, nobj};
  for (int i = 0; i < 2; i++) {
    if (cc_mtime(objs[i]) < 0 || cc_mtime(objs[i]) < cc_mtime(srcs[i]) || cc_mtime(objs[i]) < cc_mtime(hdr)) {
      snprintf(cmd, cl, "%s -O2 -w -I '%s' -c '%s' -o '%s.tmp' && mv '%s.tmp' '%s'", cc, rt, srcs[i], objs[i], objs[i],
        objs[i]);
      if (system(cmd) != 0) { free(cmd); free(out); return cc_fail(e, "the runtime does not compile"); }
    }
  }
#ifdef __APPLE__
  const char *libs = "-lm -lpthread";
#else
  const char *libs = "-lm -lpthread -ldl";
#endif
  snprintf(cmd, cl, "%s -O2 -fno-tree-slp-vectorize -w -I '%s' '%s' '%s.o' '%s' '%s' -o '%s' %s", cc, rt, cc_tmp, out, nobj, obj, out, libs);
  int rc = system(cmd);
  free(cmd);
  if (rc != 0) { free(out); return cc_fail(e, "linking failed"); }
  if (!getenv("BENDC_KEEP")) {
    size_t k = strlen(out) + 3;
    char *o = malloc(k);
    snprintf(o, k, "%s.o", out);
    unlink(o);
    free(o);
    unlink(cc_tmp);
  }
  free(out);
  return io_done(e, term_pak(CID_UNIT, 0));
}

// bendc --native: the object format bendc writes, ELF (1) but on macOS
// (Mach-O, 0).
Term cc_elf_run(Env e, Term *f, IoWork *w) {
  (void)f;
  (void)w;
#ifdef __APPLE__
  return io_done(e, 0);
#else
  return io_done(e, 1);
#endif
}

static void __attribute__((constructor)) cc_use(void) {
  io_eff(CID_CC_BEGIN, cc_begin_run, 0);
  io_eff(CID_CC_END, cc_end_run, 0);
  io_eff(CID_CC_LINK, cc_link_run, 0);
  io_eff(CID_CC_ELF, cc_elf_run, 0);
}

// IO
// ==

Term io_print_err_run(Env e, Term* f, IoWork* w) {
  io_errs(e, f[0]);
  return term_pak(CID_UNIT, 0);
}

static void __attribute__((constructor)) io_print_err_use(void) {
  io_eff(CID_IO_PRINT_ERR, io_print_err_run, 0);
}

// File
// ====

Term file_close_run(Env e, Term* f, IoWork* w) {
  close((int)io_hand_v(f[0]));
  return term_pak(CID_UNIT, 0);
}

static void __attribute__((constructor)) file_close_use(void) {
  io_eff(CID_FILE_CLOSE, file_close_run, 0);
}

// File
// ====

static void file_write_call(IoWork* w) {
  int fd = (int)w->hand;
  ssize_t n = 0;
  for (uint64_t at = 0; n >= 0 && at < w->size; at += (uint64_t)n) {
    n = write(fd, w->data + at, w->size - at);
  }
  io_sys_end(w, n);
}

static Term file_write_pack(Env e, IoWork* w) {
  Term r = io_res(e, w, term_pak(CID_UNIT, 0));
  free(w->data);
  return io_tup(e, io_hand(w->hand), r);
}

#ifdef CID_FILE_WRITE

Term file_write_run(Env e, Term* f, IoWork* w) {
  w->hand = (intptr_t)io_hand_v(f[0]);
  w->data = io_cstr(e, f[1], &w->size);
  return io_work(w, file_write_call, file_write_pack);
}

static void __attribute__((constructor)) file_write_use(void) {
  io_eff(CID_FILE_WRITE, file_write_run, 0);
}

#endif

#ifdef CID_FILE_WRITE_BYTES

// A value past 255 fails with EINVAL before any byte is written.
Term file_write_bytes_run(Env e, Term* f, IoWork* w) {
  w->hand = (intptr_t)io_hand_v(f[0]);
  w->data = io_cbuf(e, f[1], &w->size, CID_CON);
  w->code = w->data == NULL ? EINVAL : 0;
  return w->code ? file_write_pack(e, w)
    : io_work(w, file_write_call, file_write_pack);
}

static void __attribute__((constructor)) file_write_bytes_use(void) {
  io_eff(CID_FILE_WRITE_BYTES, file_write_bytes_run, 0);
}

#endif

// File
// ====

static int file_open_mode(const char* mode) {
  if (strcmp(mode, "r") == 0) {
    return O_RDONLY;
  }
  if (strcmp(mode, "w") == 0) {
    return O_WRONLY | O_CREAT | O_TRUNC;
  }
  if (strcmp(mode, "a") == 0) {
    return O_WRONLY | O_CREAT | O_APPEND;
  }
  return -1;
}

static void file_open_call(IoWork* w) {
  w->made = (intptr_t)io_sys_end(w, open(w->data, (int)w->word, 0644));
}

static Term file_open_pack(Env e, IoWork* w) {
  free(w->data);
  return io_res(e, w, io_hand(w->made));
}

Term file_open_run(Env e, Term* f, IoWork* w) {
  uint64_t mn = 0;
  w->data = io_cstr(e, f[0], &w->size);
  char* mode = io_cstr(e, f[1], &mn);
  int flags = io_nul(mode, mn) ? -1 : file_open_mode(mode);
  free(mode);
  w->word = (uint32_t)flags;
  if (io_nul(w->data, w->size) || flags < 0) {
    w->code = io_nul(w->data, w->size) ? EILSEQ : EINVAL;
    return file_open_pack(e, w);
  }
  return io_work(w, file_open_call, file_open_pack);
}

static void __attribute__((constructor)) file_open_use(void) {
  io_eff(CID_FILE_OPEN, file_open_run, 0);
}

// IO
// ==

Term io_write_run(Env e, Term* f, IoWork* w) {
  uint64_t n = 0;
  char* text = io_cstr(e, f[0], &n);
  io_out(stdout, text, n);
  free(text);
  return term_pak(CID_UNIT, 0);
}

static void __attribute__((constructor)) io_write_use(void) {
  io_eff(CID_IO_WRITE, io_write_run, 0);
}

// File
// ====

static void file_read_call(IoWork* w) {
  int fd = (int)w->hand;
  w->size = io_sys_end(w, read(fd, w->data, w->word));
}

static Term file_read_start(Term file, u64 max, IoWork* w,
  IoCall call, IoPack pack) {
  w->hand = (intptr_t)io_hand_v(file);
  w->word = max < INT32_MAX ? max : INT32_MAX;
  w->data = io_mem(malloc(w->word + 1));
  return io_work(w, call, pack);
}

#ifdef CID_FILE_READ

static Term file_read_pack(Env e, IoWork* w) {
  Term r = io_res(e, w, io_str(e, w->data, w->size));
  free(w->data);
  return io_tup(e, io_hand(w->hand), r);
}

Term file_read_run(Env e, Term* f, IoWork* w) {
  return file_read_start(f[0], f[1], w, file_read_call, file_read_pack);
}

static void __attribute__((constructor)) file_read_use(void) {
  io_eff(CID_FILE_READ, file_read_run, 0);
}

#endif

#if defined(CID_FILE_READ_BYTES) || defined(CID_FILE_READ_AT)

static Term file_read_bytes_pack(Env e, IoWork* w) {
  Term r = io_res(e, w, io_list(e, w->data, w->size));
  free(w->data);
  return io_tup(e, io_hand(w->hand), r);
}

#endif

#ifdef CID_FILE_READ_BYTES

Term file_read_bytes_run(Env e, Term* f, IoWork* w) {
  return file_read_start(f[0], f[1], w, file_read_call, file_read_bytes_pack);
}

static void __attribute__((constructor)) file_read_bytes_use(void) {
  io_eff(CID_FILE_READ_BYTES, file_read_bytes_run, 0);
}

#endif

#ifdef CID_FILE_READ_AT

// The bytes at an offset, as file_read_bytes gives them; the position of
// the file does not move.
static void file_read_at_call(IoWork* w) {
  int fd = (int)w->hand;
  w->size = io_sys_end(w, pread(fd, w->data, w->word, (off_t)w->made));
}

Term file_read_at_run(Env e, Term* f, IoWork* w) {
  w->made = (intptr_t)f[1];
  return file_read_start(f[0], f[2], w, file_read_at_call, file_read_bytes_pack);
}

static void __attribute__((constructor)) file_read_at_use(void) {
  io_eff(CID_FILE_READ_AT, file_read_at_run, 0);
}

#endif

// File
// ====

#include <sys/stat.h>

// The size in bytes, as the host reports it; a file past 4 GiB fails
// with EOVERFLOW.
static void file_size_call(IoWork* w) {
  struct stat st;
  int n = fstat((int)w->hand, &st);
  io_sys_end(w, n);
  if (n == 0) {
    w->code = st.st_size > (off_t)UINT32_MAX ? EOVERFLOW : 0;
    w->word = (u32)st.st_size;
  }
}

static Term file_size_pack(Env e, IoWork* w) {
  return io_tup(e, io_hand(w->hand), io_res(e, w, w->word));
}

Term file_size_run(Env e, Term* f, IoWork* w) {
  w->hand = (intptr_t)io_hand_v(f[0]);
  return io_work(w, file_size_call, file_size_pack);
}

static void __attribute__((constructor)) file_size_use(void) {
  io_eff(CID_FILE_SIZE, file_size_run, 0);
}

// IO
// ==

Term io_get_env_run(Env e, Term* f, IoWork* w) {
  uint64_t n = 0;
  char* name = io_cstr(e, f[0], &n);
  const char* got = io_nul(name, n) ? NULL : getenv(name);
  free(name);
  return got == NULL ? io_fail(e, ENOENT, NULL)
    : io_done(e, io_str(e, got, strlen(got)));
}

static void __attribute__((constructor)) io_get_env_use(void) {
  io_eff(CID_IO_GET_ENV, io_get_env_run, 0);
}

// Hub imports
// ===========
//
// `import 0x<hash>/path.bend as P` names a package by content hash. As the
// official bend does, the package's files are fetched from the hub (by
// default https://hub.bend-lang.com, or $BEND_HUB) into $BEND_LIB (default
// ~/.bend/lib) the first time: <hub>/<pkg>/manifest lists "sha256 path"
// lines and must hash to the package name; each file must hash to its line.

#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

static const uint32_t hub_k[64] = {
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2};

#define HUB_ROR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

static void hub_block(uint32_t h[8], const unsigned char *p) {
  uint32_t w[64];
  for (int i = 0; i < 16; i++) w[i] = (uint32_t)p[4 * i] << 24 | (uint32_t)p[4 * i + 1] << 16 | (uint32_t)p[4 * i + 2] << 8 | p[4 * i + 3];
  for (int i = 16; i < 64; i++) {
    uint32_t s0 = HUB_ROR(w[i - 15], 7) ^ HUB_ROR(w[i - 15], 18) ^ (w[i - 15] >> 3);
    uint32_t s1 = HUB_ROR(w[i - 2], 17) ^ HUB_ROR(w[i - 2], 19) ^ (w[i - 2] >> 10);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  uint32_t a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], k = h[7];
  for (int i = 0; i < 64; i++) {
    uint32_t t1 = k + (HUB_ROR(e, 6) ^ HUB_ROR(e, 11) ^ HUB_ROR(e, 25)) + ((e & f) ^ (~e & g)) + hub_k[i] + w[i];
    uint32_t t2 = (HUB_ROR(a, 2) ^ HUB_ROR(a, 13) ^ HUB_ROR(a, 22)) + ((a & b) ^ (a & c) ^ (b & c));
    k = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
  }
  h[0] += a; h[1] += b; h[2] += c; h[3] += d; h[4] += e; h[5] += f; h[6] += g; h[7] += k;
}

// The SHA-256 of n bytes, as 64 hex digits.
static void hub_sha256(const char *data, size_t n, char out[65]) {
  uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
  const unsigned char *p = (const unsigned char *)data;
  size_t i = 0;
  for (; i + 64 <= n; i += 64) hub_block(h, p + i);
  unsigned char tail[128] = {0};
  size_t r = n - i;
  memcpy(tail, p + i, r);
  tail[r] = 0x80;
  size_t len = r + 1 + 8 <= 64 ? 64 : 128;
  uint64_t bits = (uint64_t)n * 8;
  for (int j = 0; j < 8; j++) tail[len - 1 - j] = (unsigned char)(bits >> (8 * j));
  hub_block(h, tail);
  if (len == 128) hub_block(h, tail + 64);
  for (int j = 0; j < 8; j++) snprintf(out + 8 * j, 9, "%08x", h[j]);
}

// Only plain path characters reach the shell or the file system.
static int hub_safe(const char *s) {
  if (*s == 0) return 0;
  for (const char *c = s; *c; c++) {
    if (!(isalnum((unsigned char)*c) || strchr("._-/:", *c))) return 0;
  }
  return strstr(s, "..") == NULL;
}

// GETs url with curl; returns a malloc'd body (NULL on failure).
static char *hub_fetch(const char *url, size_t *n) {
  if (!hub_safe(url)) return NULL;
  size_t cl = strlen(url) + 64;
  char *cmd = malloc(cl);
  snprintf(cmd, cl, "curl -fsSL --max-time 60 '%s'", url);
  FILE *p = popen(cmd, "r");
  free(cmd);
  if (p == NULL) return NULL;
  size_t cap = 4096, len = 0;
  char *buf = malloc(cap);
  size_t k;
  while ((k = fread(buf + len, 1, cap - len, p)) > 0) {
    len += k;
    if (len == cap) buf = realloc(buf, cap *= 2);
  }
  int st = pclose(p);
  if (st != 0) { free(buf); return NULL; }
  buf[len] = 0;
  *n = len;
  return buf;
}

static int hub_mkdirs(char *path) {
  for (char *c = path + 1; *c; c++) {
    if (*c == '/') {
      *c = 0;
      if (mkdir(path, 0755) != 0 && errno != EEXIST) { *c = '/'; return -1; }
      *c = '/';
    }
  }
  return 0;
}

static Term hub_err(Env e, const char *hub, const char *sub, const char *hash) {
  size_t n = strlen(hub) + strlen(sub) + strlen(hash) + 64;
  char *m = malloc(n);
  snprintf(m, n, "expected a file at %s/%s hashing to %s", hub, sub, hash);
  Term t = io_fail(e, 1, m);
  free(m);
  return t;
}

// Fetches the hub file sub, checking that its SHA-256 starts with hash.
static char *hub_get(const char *hub, const char *sub, const char *hash, size_t *n) {
  size_t ul = strlen(hub) + strlen(sub) + 2;
  char *url = malloc(ul);
  snprintf(url, ul, "%s/%s", hub, sub);
  char *src = hub_fetch(url, n);
  free(url);
  if (src == NULL) return NULL;
  char sum[65];
  hub_sha256(src, *n, sum);
  if (strlen(hash) < 32 || strncmp(sum, hash, strlen(hash)) != 0) { free(src); return NULL; }
  return src;
}

static Term hub_ensure(Env e, const char *lib, const char *hub, const char *rel) {
  size_t pl = strlen(lib) + strlen(rel) + 2;
  char *at = malloc(pl);
  snprintf(at, pl, "%s/%s", lib, rel);
  struct stat st;
  int have = stat(at, &st) == 0;
  free(at);
  if (have) return io_done(e, term_pak(CID_UNIT, 0));
  const char *slash = strchr(rel, '/');
  if (slash == NULL || rel[0] != '0' || rel[1] != 'x') return io_fail(e, 1, "a hub import (0x<hash>/<path>.bend)");
  char *pkg = strndup(rel, (size_t)(slash - rel));
  char *msub = malloc(strlen(pkg) + 16);
  sprintf(msub, "%s/manifest", pkg);
  size_t mn = 0;
  char *man = hub_get(hub, msub, pkg + 2, &mn);
  if (man == NULL) {
    Term t = hub_err(e, hub, msub, pkg + 2);
    free(msub); free(pkg);
    return t;
  }
  free(msub);
  Term out = io_done(e, term_pak(CID_UNIT, 0));
  for (char *line = strtok(man, "\n"); line != NULL; line = strtok(NULL, "\n")) {
    char *sp = strchr(line, ' ');
    if (sp == NULL) continue;
    *sp = 0;
    const char *h = line, *p = sp + 1;
    size_t sl = strlen(pkg) + strlen(p) + 2;
    char *sub = malloc(sl);
    snprintf(sub, sl, "%s/%s", pkg, p);
    size_t fn = 0;
    char *src = hub_safe(p) && p[0] != '/' ? hub_get(hub, sub, h, &fn) : NULL;
    if (src == NULL) {
      out = hub_err(e, hub, sub, h);
      free(sub);
      break;
    }
    size_t fl = strlen(lib) + strlen(sub) + 2;
    char *file = malloc(fl);
    snprintf(file, fl, "%s/%s", lib, sub);
    FILE *fp = NULL;
    if (hub_mkdirs(file) == 0) fp = fopen(file, "wb");
    int ok = fp != NULL && fwrite(src, 1, fn, fp) == fn;
    if (fp) fclose(fp);
    free(file);
    free(src);
    free(sub);
    if (!ok) { out = io_fail(e, errno ? (u32)errno : 1, NULL); break; }
  }
  free(man);
  free(pkg);
  return out;
}

Term hub_ensure_run(Env e, Term *f, IoWork *w) {
  (void)w;
  u64 n;
  char *lib = io_cstr(e, f[0], &n), *hub = io_cstr(e, f[1], &n), *rel = io_cstr(e, f[2], &n);
  Term r = hub_ensure(e, lib, hub, rel);
  free(lib);
  free(hub);
  free(rel);
  return r;
}

static void __attribute__((constructor)) hub_ensure_use(void) {
  io_eff(CID_HUB_ENSURE, hub_ensure_run, 0);
}

// IO
// ==

Term io_print_run(Env e, Term* f, IoWork* w) {
  uint64_t n = 0;
  char* text = io_cstr(e, f[0], &n);
  io_out(stdout, text, n);
  io_out(stdout, "\n", 1);
  free(text);
  return term_pak(CID_UNIT, 0);
}

static void __attribute__((constructor)) io_print_use(void) {
  io_eff(CID_IO_PRINT, io_print_run, 0);
}

// IO
// ==

Term io_args_run(Env e, Term* f, IoWork* w) {
  Term xs = term_pak(CID_NIL, 0);
  for (int i = io_argc; i > 0; i -= 1) {
    const char* a = io_argv[i - 1];
    xs = io_node(e, CID_CON, io_str(e, a, strlen(a)), xs);
  }
  return xs;
}

static void __attribute__((constructor)) io_args_use(void) {
  io_eff(CID_IO_ARGS, io_args_run, 0);
}


#ifdef __TINYC__
// tcc ignores __attribute__((constructor)): main calls these
static void bend_ctors(void) {
  cc_use();
  io_print_err_use();
  file_close_use();
  file_write_use();
  file_write_bytes_use();
  file_open_use();
  io_write_use();
  file_read_use();
  file_read_bytes_use();
  file_read_at_use();
  file_size_use();
  io_get_env_use();
  hub_ensure_use();
  io_print_use();
  io_args_use();
}
#endif
